// 1.77: ご近所の噂の中継点（市井の生活雑談「既存キャラ（菊女・早苗・茜女・綾女・阿古）と結び、噂の中継点にする」）
Object.assign(HUBS,{町の井戸端:['kikume','sanae','akane','ayame','ako']});


// ---------------- 組み立て ----------------
const byId={};L.people.forEach(p=>byId[p.id]=p);

// つながり（src＋交差点。双方向）
const G={};const link=(a,b)=>{if(a===b||!byId[a]||!byId[b])return;(G[a]=G[a]||new Set).add(b);(G[b]=G[b]||new Set).add(a);};
L.people.forEach(p=>(p.kb?.src||[]).forEach(s=>link(p.id,s)));
Object.values(HUBS).forEach(h=>h.forEach(a=>h.forEach(b=>link(a,b))));
function hops(from){const d={[from]:0},q=[from];while(q.length){const a=q.shift();(G[a]||[]).forEach(b=>{if(d[b]==null){d[b]=d[a]+1;q.push(b);}});}return d;}
const hopCache={};const hopsFrom=o=>hopCache[o]||(hopCache[o]=hops(o));

// 深さ：自分の分野の知識と、出どころからの距離の大きいほう
// ---- 身分・立場・忠誠の軸（2026-09-30）。people の axis（台帳 game.axis）: mibun・house（仕える家）・tachiba（右大臣方／左大臣方／中立）・chusei（主家への忠誠0〜3）
//  ①話題の house が自分の仕える家で、忠誠が2以上なら、主家の内情は深さ1（噂）までしか話さない（guard）。忠誠の低い者から真相が漏れる
//  ②話題の by に立場ごとの言い方があれば、その立場の言い方で語る（同じ出来事でも右大臣方と左大臣方で言うことが違う）
const guarded=(p,t)=>!!t.house&&p.axis?.house===t.house&&(p.axis.chusei??0)>=2;
TOPICS.red_tassel.house='左大臣家';
TOPICS.kiyoyuki_letter.house='右大臣家'; // 1.74: 右大臣家の内のこと＝忠誠の高い家司・車副は噂の深さまでしか話さない
