// 着手案29：国へ帰る人夫と、都に居ついた者たち（2026-10-04 22時に入れた・井内さん「諸国から荷を運んできた人夫のうち、国へ帰ろうと旅立つもの、
//   平安京で浮浪者となって同郷の仲間と道端で寝て暮らすもの…庶民の暮らしをもう少し厚く」）
